import './realtor-runtime-20261019.mjs';import fs from 'node:fs/promises';const{db}=await import('./reply-runtime-20261015.mjs');const out=[];
for(const r of JSON.parse(await fs.readFile('artifacts/partnership-nudges-20261019/review.json'))){const phone=r.contact.phone;const peers=await db('market_contacts',{phone:'eq.'+phone});const sms=await db('sms_messages',{or:`(from_number.eq.${phone},to_number.eq.${phone})`,order:'created_at.desc',limit:'30'});const calls=await db('call_recordings',{phone_number:'eq.'+phone,order:'created_at.desc',limit:'10'});const threads=[];for(const c of peers)threads.push({id:c.id,thread:await db('market_touches',{contact_id:'eq.'+c.id,order:'created_at.desc',limit:'10'})});out.push({name:r.contact.name,peers,sms,calls,threads});console.log(JSON.stringify({name:r.contact.name,peers:peers.map(c=>({id:c.id,name:c.name,city:c.city,dnc:c.do_not_contact,suppressed:c.cross_channel_suppressed_at})),sms:sms.map(x=>({at:x.created_at,body:x.body,direction:x.direction,from:x.from_number})),calls}));}
const{openZohoMailbox}=await import('../lib/partnership-core/zoho.mjs');const m=await openZohoMailbox('saturn');for(const query of ['sender:tailoredroomshomestaging.com','to:Angeladumont@tailoredroomshomestaging.com']){const msgs=await m.request('/accounts/'+m.accountId+'/messages/search?'+new URLSearchParams({searchKey:query,start:'1',limit:'200',includeto:'true'}));out.push({query,messages:msgs});console.log(JSON.stringify({query,messages:msgs}));}await fs.writeFile('artifacts/partnership-nudges-20261019/cross-channel.json',JSON.stringify(out,null,2));
